UPDATE app_state SET data=json_set(data,'$.feedbackMessages',json((
SELECT json_group_array(json(CASE WHEN json_extract(value,'$.id')='67f5e8a1-29e0-43f5-9089-35ec957b27db' THEN json_patch(value,json_object('status','approved','adminComment','Etapa 1 publicada na versão 141: página Álbum de cartas, três coleções com cinco cartas cada, progresso, montagem que consome uma de cada sem duplicação e uso/remoção da insígnia conquistada. Validado em celular/computador e temas claro/escuro. Nenhum brinde ou moeda foi concedido. Ainda pendentes para a próxima etapa: distribuição por engajamento e troca de cartas; por isso a solicitação completa permanece em andamento.','updatedAt',strftime('%Y-%m-%dT%H:%M:%fZ','now'))) ELSE value END)) FROM json_each(app_state.data,'$.feedbackMessages')
))),revision=revision+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=1;
